/**
 * @fileoverview BurnBench evidence-export loader + presentation maps.
 *
 * Canonical data file: `website/public/data/bench.json` — regenerated by the
 * BurnBench pipeline (contract: recommendation-platform-contracts.md §3) and
 * served verbatim at `/data/bench.json`. Pages read it here at build time, so
 * every bench page is fully static and rebuilds pick up pipeline refreshes.
 *
 * The loader is deliberately shape-tolerant: the export's harness/model ids,
 * family scopes, and ranges evolve with the pipeline, so colors, logos,
 * monograms, and chart domains all fall back deterministically for ids the
 * site doesn't know yet.
 *
 * Presentation maps (brand colors, logo paths) live here, not in the JSON:
 * the pipeline owns numbers, the site owns how they look. Logos are the real
 * brand assets already served from `/brand/providers/` (contract §5b) —
 * never hotlinked, never re-hosted.
 */

import { readFileSync } from "node:fs";
import { join } from "node:path";

/* ---------- contract §3 types ---------- */

export interface BenchScope {
  family: string | null;
  language: string | null;
  platform: string | null;
}

export interface BenchModel {
  id: string;
  display: string;
  provider: string;
}

export interface BenchHarness {
  id: string;
  display: string;
}

export type BenchConfidence = "high" | "medium" | "low";
export type BenchEvidence = "measured" | "inferred";

export interface BenchStack {
  harness: string;
  model: string;
  config: string;
  scope: BenchScope;
  n: number;
  strict_rate: number;
  solution_rate: number;
  ci95: [number, number];
  cost_usd_median: number | null;
  wall_seconds_median: number | null;
  tokens_median: number | null;
  arena_bt: number | null;
  confidence: BenchConfidence;
  evidence: BenchEvidence;
}

export interface BenchFrontierPoint {
  harness: string;
  model: string;
  scope: BenchScope;
  solution_rate: number;
  cost_usd_median: number;
  wall_seconds_median: number;
}

export interface BenchArenaRating {
  harness: string;
  model: string;
  bt: number;
  ci95: [number, number];
  votes: number;
}

export interface BenchDoc {
  schema_version: number;
  generated_at_utc: string;
  source: {
    trees: string[];
    cells_measured: number;
    cells_excluded: number;
    runs_sha256: string;
  };
  models: BenchModel[];
  harnesses: BenchHarness[];
  stacks: BenchStack[];
  frontier: BenchFrontierPoint[];
  arena: { votes: number; ratings: BenchArenaRating[] };
}

/* ---------- build-time read (pages are static) ---------- */

const raw = readFileSync(join(process.cwd(), "public", "data", "bench.json"), "utf8");
export const BENCH: BenchDoc = JSON.parse(raw) as BenchDoc;

